<?php
require dirname(__DIR__).'/_init.php';use App\Core\AccessControl;use App\Core\Database;use App\Core\CSRF;use App\Models\Appointment;use App\Exceptions\SlotUnavailableException;
AccessControl::require('appointments.manage');$db=Database::connection();$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){CSRF::verify();try{$pid=(int)($_POST['patient_id']??0);$doc=(int)($_POST['doctor_id']??0);$date=$_POST['appointment_date']??'';$time=$_POST['appointment_time']??'';
if(!$pid||!$doc||!$date||!$time||strtotime($date)<strtotime(date('Y-m-d')))throw new RuntimeException('Select a patient, doctor and a valid future date.');
$doctor=$db->prepare("SELECT employment_type,next_visit_date,next_visit_duration FROM doctors WHERE id=? AND is_active=1");$doctor->execute([$doc]);$dr=$doctor->fetch();if(!$dr)throw new RuntimeException('Doctor not found.');
if($dr['employment_type']==='visiting' && $dr['next_visit_date']!==$date)throw new RuntimeException('This visiting doctor is only bookable on the configured visit date.');
Appointment::book(['patient_id'=>$pid,'doctor_id'=>$doc,'appointment_date'=>$date,'appointment_time'=>$time]);header('Location: /appointments/index.php');exit;
}catch(Throwable $e){$err=$e instanceof SlotUnavailableException?$e->getMessage():$e->getMessage();}}
$patients=$db->query("SELECT id,patient_number,full_name FROM patients ORDER BY full_name")->fetchAll();$doctors=$db->query("SELECT id,name FROM doctors WHERE is_active=1 ORDER BY name")->fetchAll();require dirname(__DIR__).'/_layout_top.php';?>
<h2>Book appointment</h2><?php if($err):?><div class="alert alert-danger"><?=e($err)?></div><?php endif;?><form method="post" class="card p-4"><?=CSRF::field()?><div class="mb-3"><label class="form-label">Patient</label><select class="form-select" name="patient_id" required><option value="">Select patient</option><?php foreach($patients as $p):?><option value="<?=$p['id']?>"><?=e($p['patient_number'].' - '.$p['full_name'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Doctor</label><select class="form-select" name="doctor_id" required><option value="">Select doctor</option><?php foreach($doctors as $d):?><option value="<?=$d['id']?>"><?=e($d['name'])?></option><?php endforeach;?></select></div><div class="row"><div class="col-md-6"><label class="form-label">Date</label><input class="form-control" type="date" min="<?=date('Y-m-d')?>" name="appointment_date" required></div><div class="col-md-6"><label class="form-label">Time</label><input class="form-control" type="time" name="appointment_time" required></div></div><button class="btn btn-primary mt-4">Confirm booking</button></form><?php require dirname(__DIR__).'/_layout_bottom.php';?>
